<#!n.SYNOPSISn    Convert the C-Com WP working log (C:\CComWP\Log\temp.log) to CSV.n.n.DESCRIPTIONn    Fixed-path variant of fastlog2csv.ps1 for Windows PowerShell 5.1.n    Reads   C:\CComWP\Log\temp.logn    Writes  C:\CComWP\Log\FAST-YYYY-MM-DDTHHMM.csvn    The timestamp is the log file's last-modified time, i.e. when the n    logging session ended, so re-running the conversion on the same logn    produces the same file name (overwritten, not duplicated).n.n    Format (reverse-engineered):n      0x000   ASCII version ("22"), u16 channel count N, N u16 channel idsn      0x204   N channel definitions, 58 bytes each:n                name[16] units[8] u16 u16 u16 f32_scale f32_offsetn                u16 raw_min u16 raw_max f32 disp_max f32 disp_min fmt[8]n      defs+22 data records: N x u16 raw values + u32 timestamp (ms)n      Engineering value = raw * scale + offset.n      MAP stored as raw counts (scale 1.0) is converted to psia usingn      14.7/245 (calibrated from the engine-off atmospheric reading).n      Coolant and air temp remain raw sensor counts.n.n.EXAMPLEn    powershell -ExecutionPolicy Bypass -File .\fastlog2csv-temp.ps1n#>nSet-StrictMode -Version 2n$ErrorActionPreference = 'Stop'nn$src    = 'C:\CComWP\Log\temp.log'n$outDir = Split-Path -Parent $srcnn$inv       = [System.Globalization.CultureInfo]::InvariantCulture   # always '.' decimalsn$utf8NoBom = New-Object System.Text.UTF8Encoding($false)n$DEF0  = 0x204n$DEFSZ = 58n$MAP_PSIA_PER_COUNT = 14.7 / 245nnfunction Get-CString([byte[]]$buf, [int]$off, [int]$len) {n    $end = $offn    while ($end -lt $off + $len -and $buf[$end] -ne 0) { $end++ }n    return [System.Text.Encoding]::ASCII.GetString($buf, $off, $end - $off).Trim()n}nnfunction Format-CsvField([string]$s) {n    if ($s -match '[",\r\n]') { return '"' + $s.Replace('"', '""') + '"' }n    return $sn}nnfunction Format-Num([double]$v) {n    return [Math]::Round($v, 4).ToString('0.0###', $inv)n}nn$exitCode = 0ntry {n    if (-not (Test-Path -LiteralPath $src)) { throw "input not found: $src" }nn    $d = [System.IO.File]::ReadAllBytes($src)n    if ($d.Length -lt 0x210) { throw "${src}: file too small to be a FAST log" }nn    $nchan = [BitConverter]::ToUInt16($d, 2)n    if ($nchan -lt 1 -or $nchan -gt 32) {n        throw "${src}: implausible channel count $nchan; not a FAST Classic log?"n    }n    if ($d.Length -lt $DEF0 + $DEFSZ * $nchan + 22) { throw "${src}: truncated channel header" }nn    # Channel definitionsn    $cols   = New-Object string[] $nchann    $scale  = New-Object double[] $nchann    $offset = New-Object double[] $nchann    for ($i = 0; $i -lt $nchan; $i++) {n        $o     = $DEF0 + $DEFSZ * $in        $name  = Get-CString $d $o 16n        $units = Get-CString $d ($o + 16) 8n        $sc    = [double][BitConverter]::ToSingle($d, $o + 30)n        $off   = [double][BitConverter]::ToSingle($d, $o + 34)nn        if (-not $units -or $name.Contains($units)) { $col = $name }n        else { $col = "$name [$units]" }nn        if ($name.ToUpper().StartsWith('MAP') -and $sc -eq 1.0) { $sc = $MAP_PSIA_PER_COUNT }nn        $cols[$i] = $col; $scale[$i] = $sc; $offset[$i] = $offn    }nn    # Data recordsn    $data0 = $DEF0 + $DEFSZ * $nchan + 22n    $recsz = 2 * $nchan + 4n    $nrec  = [Math]::Floor(($d.Length - $data0) / $recsz)nn    $lines = New-Object System.Collections.Generic.List[string]n    $hdr = @('Time_s') + ($cols | ForEach-Object { Format-CsvField $_ })n    $lines.Add($hdr -join ',')nn    $prevTs = -1L; $firstT = $null; $lastT = $null; $count = 0n    $fields = New-Object string[] ($nchan + 1)n    $o = $data0n    for ($r = 0; $r -lt $nrec; $r++) {n        $ts = [long][BitConverter]::ToUInt32($d, $o + 2 * $nchan)n        if ($ts -lt $prevTs) { break }   # non-monotonic time: past end of datan        $prevTs = $tsn        $t = $ts / 1000.0n        if ($null -eq $firstT) { $firstT = $t }n        $lastT = $tnn        $fields[0] = $t.ToString('0.0##', $inv)n        for ($c = 0; $c -lt $nchan; $c++) {n            $raw = [BitConverter]::ToUInt16($d, $o + 2 * $c)n            $fields[$c + 1] = Format-Num ($raw * $scale[$c] + $offset[$c])n        }n        $lines.Add($fields -join ',')n        $count++n        $o += $recszn    }n    if ($count -eq 0) { throw "${src}: no valid data records found" }nn    # Output name from the log's last-modified time, e.g. FAST-2025-12-07T1436.csvn    $stamp = (Get-Item -LiteralPath $src).LastWriteTime.ToString("yyyy-MM-dd'T'HHmm", $inv)n    $dst   = Join-Path $outDir "FAST-$stamp.csv"nn    [System.IO.File]::WriteAllLines($dst, $lines.ToArray(), $utf8NoBom)n    $dur = ($lastT - $firstT).ToString('0.0', $inv)n    Write-Host "${src}: $count records, $nchan channels, ${dur}s -> $dst"n}ncatch {n    Write-Host "ERROR: $($_.Exception.Message)" -ForegroundColor Redn    $exitCode = 1n}nfinally {n    [void](Read-Host 'Press Enter to exit')n}nnif ($exitCode -ne 0) { exit $exitCode }n